    "questionEn": "A particle moves outward from $x = 1\\text{ m}$ in a straight line with acceleration $a = -\\frac{18}{x^2}\\text{ m/s}^2$ and initial velocity $v_0 = \\sqrt{136}\\text{ m/s}$. Find the limiting velocity of the particle as $x \\to \\infty$.",
    "questionAr": "يتحرك جسيم مبتعداً في خط مستقيم من $x = 1\\text{ م}$ بعجلة $a = -\\frac{18}{x^2}\\text{ م/ث}^2$ وبسرعة ابتدائية $v_0 = \\sqrt{136}\\text{ م/ث}$. أوجد السرعة التي يقترب منها الجسيم عندما $x \\to \\infty$.",
    "optionsEn": [
      "$10\\text{ m/s}$",
      "$11\\text{ m/s}$",
      "$13\\text{ m/s}$",
      "$15\\text{ m/s}$"
    ],
    "optionsAr": [
      "10 م/ث",
      "11 م/ث",
      "13 م/ث",
      "15 م/ث"
    ],
    "correctAnswer": "$10\\text{ m/s}$",
    "correctIndex": 0,
    "hintEn": "Integrate $v dv = a dx = -\\frac{${2 * factor}}{x^2} dx$, and let $x \\to \\infty$.",
    "hintAr": "كامل: $v dv = -\\frac{${2 * factor}}{x^2} dx$، ثم احسب النهاية عندما $x \\to \\infty$.",
    "stepByStepSolutionEn": [
      "1. $\\int_{v_0}^v v dv = \\int_1^x -\\frac{18}{u^2} du = \\left[\\frac{18}{u}\\right]_1^x = \\frac{18}{x} - 18$.",
      "2. $\\frac{1}{2}(v^2 - 136) = \\frac{18}{x} - 18$.",
      "3. Multiply by 2: $v^2 - 136 = \\frac{36}{x} - 36$.",
      "4. As $x \\to \\infty$, $\\frac{36}{x} \\to 0$, so $v^2 = 136 - 36 = 100$.",
      "5. Therefore, $v = \\sqrt{100} = 10\\text{ m/s}$."
    ],
    "stepByStepSolutionAr": [
      "١. $\\int v dv = \\int -\\frac{18}{x^2} dx \\implies \\frac{1}{2}(v^2 - 136) = \\frac{18}{x} - 18$.",
      "٢. بالضرب في ٢: $v^2 = 136 - 36 + \\frac{36}{x}$.",
      "٣. عندما $x \\to \\infty$ ينعدم الكسر وتصبح $v^2 = 100$.",
      "٤. إذن السرعة النهائية $v = 10\\text{ م/ث}$."
    ],
    "teacherTipEn": "A classic Thanaweya question modeling celestial gravitational mechanics.",
    "teacherTipAr": "مسألة امتحانية كلاسيكية تعبر عن ميكانيكا الجاذبية الفلكية وتكامل الدوال الكسرية."
