    "questionAr": "يتحرك جسيم في المستوى بمتجه موضع $\\vec{r}(t) = (3t)\\hat{i} + (1t^2)\\hat{j}\\text{ م}$. أوجد الإحداثي الصادي للجسيم عندما يبلغ إحداثيه السيني $6\\text{ م}$.",
