    "questionAr": "بدأت سيارة حركتها من السكون وتسارعت بعجلة منتظمة $2\\text{ م/ث}^2$ لمدة $t = 1\\text{ ث}$. ثم استخدمت الفرامل فتباطأت بعجلة منتظمة $1\\text{ م/ث}^2$ حتى توقفت تماماً. أوجد المسافة الكلية التي قطعتها السيارة.",
