    "hintAr": "احسب أقصى سرعة $v_1 = a_1 t_1$، ثم اجمع مسافتي المرحلتين $s_1 = \\frac{1}{2}a_1 t_1^2$ و $s_2 = \\frac{v_1^2}{2a_2}$.",
